#include <bits/stdc++.h>
using namespace std;
struct Test { virtual ~Test() {} virtual void Body() = 0; bool failed = false; };
struct Info { string name; function<Test*()> make; };
// Function-local static: built on first use, so registration order across files is safe
vector<Info>& registry() { static vector<Info> r; return r; }
Test* current = nullptr;
struct Registrar { Registrar(string n, function<Test*()> f) { registry().push_back({n, f}); } };
// TEST expands to a class plus a static registrar object that runs before main
#define TEST(S, N) struct S##_##N : Test { void Body() override; }; \
  static Registrar reg_##S##_##N(#S "." #N, [] { return (Test*)new S##_##N; }); \
  void S##_##N::Body()
#define EXPECT_EQ(a, b) do { if (!((a) == (b))) { current->failed = true; \
  cout << "    FAIL: " << #a << " != " << #b << "\n"; } } while (0)

TEST(Math, Add) { EXPECT_EQ(1 + 1, 2); }
TEST(Math, Bad) { EXPECT_EQ(2 * 2, 5); }
TEST(Str, Len)  { EXPECT_EQ(string("abc").size(), 3u); }

int main() {
  cout << "registered before main: " << registry().size() << " tests\n";
  int failed = 0;
  for (auto& info : registry()) {          // the "RUN_ALL_TESTS" loop
    Test* t = info.make();                 // fresh object per test
    current = t;
    cout << "[ RUN ] " << info.name << "\n";
    t->Body();
    if (t->failed) ++failed;
    cout << (t->failed ? "[ FAILED ] " : "[ OK ] ") << info.name << "\n";
    delete t;
  }
  cout << failed << " failed; exit code " << (failed ? 1 : 0) << "\n";
  return failed ? 1 : 0;
}

#include <bits/stdc++.h>
using namespace std;
int failures = 0;
// EXPECT records the failure and keeps going
#define EXPECT_TRUE(c) do { if (!(c)) { ++failures; cout << "  EXPECT failed: " #c "\n"; } } while (0)
// ASSERT records the failure and returns from the current void function
#define ASSERT_TRUE(c) do { if (!(c)) { ++failures; cout << "  ASSERT failed: " #c "\n"; return; } } while (0)

struct Fixture {            // constructor = SetUp, destructor = TearDown
  vector<int> v;
  Fixture() : v{1, 2, 3} {} // fresh state for every test keeps tests isolated
};

void testExpect() {
  Fixture f;
  cout << "testExpect\n";
  EXPECT_TRUE(f.v.size() == 4);  // fails, but we continue
  EXPECT_TRUE(f.v[0] == 1);      // passes
  EXPECT_TRUE(f.v[1] == 9);      // fails too: one run shows both problems
}
void testAssert() {
  Fixture f;
  cout << "testAssert\n";
  ASSERT_TRUE(f.v.size() == 4);  // fails: stop here, indexing below would be unsafe
  cout << "  never printed\n";
  EXPECT_TRUE(f.v[3] == 0);
}
int main() {
  testExpect();
  testAssert();
  cout << "total failures: " << failures << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Code under test: is this a plausible port number string?
bool validPort(const string& s) {
  if (s.empty() || s.size() > 5) return false;
  for (char c : s) if (!isdigit((unsigned char)c)) return false;
  int n = stoi(s);
  return n >= 1 && n <= 65535;
}
struct Case { string name; string input; bool expected; };

int main() {
  // One behaviour, many rows: what TEST_P + INSTANTIATE_TEST_SUITE_P generates
  vector<Case> table = {
    {"min", "1", true}, {"max", "65535", true}, {"zero", "0", false},
    {"too_big", "65536", false}, {"letters", "80a", false}, {"empty", "", false},
  };
  int bad = 0;
  for (auto& c : table) {
    bool got = validPort(c.input);
    // The name makes a failure say which case broke
    cout << (got == c.expected ? "[ OK ] " : "[ FAIL ] ") << "Ports/" << c.name
         << " input='" << c.input << "'\n";
    if (got != c.expected) ++bad;
  }
  cout << (table.size() - bad) << "/" << table.size() << " passed\n";
}

#include <bits/stdc++.h>
using namespace std;
// The seam: code depends on this interface, injected through the constructor
struct Mailer { virtual ~Mailer() {} virtual bool send(const string& to, const string& body) = 0; };

struct StubMailer : Mailer {          // stub: canned answer
  bool send(const string&, const string&) override { return true; }
};
struct FakeMailer : Mailer {          // fake: working, simple implementation
  vector<string> outbox;
  bool send(const string& to, const string& body) override { outbox.push_back(to + ":" + body); return true; }
};
struct MockMailer : Mailer {          // mock: records calls so the test can verify them
  int calls = 0; string lastTo;
  bool send(const string& to, const string&) override { ++calls; lastTo = to; return true; }
};
struct Signup {
  Mailer& m;
  explicit Signup(Mailer& mm) : m(mm) {}
  bool registerUser(const string& email) { return m.send(email, "welcome"); }
};
int main() {
  StubMailer stub; Signup a(stub);
  cout << "stub: registerUser -> " << a.registerUser("a@x.test") << "\n";
  FakeMailer fake; Signup b(fake); b.registerUser("b@x.test");
  cout << "fake: outbox size " << fake.outbox.size() << ", first " << fake.outbox[0] << "\n";
  MockMailer mock; Signup c(mock); c.registerUser("c@x.test");
  // Interaction check: the email must be sent exactly once, to the right person
  cout << "mock: calls=" << mock.calls << " to=" << mock.lastTo
       << (mock.calls == 1 && mock.lastTo == "c@x.test" ? " (verified)" : " (WRONG)") << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// A tiny model of ASan's redzones: poison bytes around the user area
struct Guarded {
  static const int RZ = 8;
  vector<unsigned char> mem; size_t n;
  explicit Guarded(size_t size) : mem(size + 2 * RZ, 0xFD), n(size) {
    for (size_t i = 0; i < n; ++i) mem[RZ + i] = 0;   // user bytes start zeroed
  }
  unsigned char& at(long i) { return mem[RZ + i]; }   // like an unchecked a[i]
  bool intact() const {                               // did anyone touch a redzone?
    for (int i = 0; i < RZ; ++i)
      if (mem[i] != 0xFD || mem[RZ + n + i] != 0xFD) return false;
    return true;
  }
};
int main() {
  Guarded buf(4);
  for (long i = 0; i < 4; ++i) buf.at(i) = 1;         // correct: indexes 0..3
  cout << "after correct writes, redzones intact: " << buf.intact() << "\n";
  for (long i = 0; i <= 4; ++i) buf.at(i) = 1;        // bug: off-by-one writes index 4
  cout << "after off-by-one write, redzones intact: " << buf.intact() << "\n";
  cout << (buf.intact() ? "no error" : "ERROR: heap-buffer-overflow detected at redzone") << "\n";
  // Real ASan checks shadow memory on every access, so it stops at the bad write itself.
}

#include <bits/stdc++.h>
using namespace std;
// Vector-clock race detection for two threads and one lock, as TSan does it
struct State {
  array<int, 2> clk[2] = {{0, 0}, {0, 0}};  // each thread's vector clock
  array<int, 2> lockClk = {0, 0};           // clock stored in the mutex
  int lastTid = -1, lastEpoch = 0;          // shadow cell of variable x
  void tick(int t) { clk[t][t]++; }
  void release(int t) { for (int i = 0; i < 2; ++i) lockClk[i] = max(lockClk[i], clk[t][i]); tick(t); }
  void acquire(int t) { for (int i = 0; i < 2; ++i) clk[t][i] = max(clk[t][i], lockClk[i]); }
  bool write(int t) {
    tick(t);
    // race if the last write by another thread is NOT before us (no happens-before)
    bool race = lastTid != -1 && lastTid != t && lastEpoch > clk[t][lastTid];
    lastTid = t; lastEpoch = clk[t][t];
    return race;
  }
};
int main() {
  State a;                                   // scenario A: no synchronisation
  a.write(0);
  cout << "A: T0 writes x, T1 writes x without lock -> race=" << a.write(1) << "\n";
  State b;                                   // scenario B: unlock then lock
  b.write(0); b.release(0);                  // T0: write x; unlock(m)
  b.acquire(1);                              // T1: lock(m) joins T0's clock
  cout << "B: same writes ordered by the mutex      -> race=" << b.write(1) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Warning ratchet: keys have no line numbers, so edits elsewhere do not change them
using Counts = map<string, int>;
int main() {
  Counts baseline = {{"a.cpp|-Wshadow|x", 3}, {"a.cpp|-Wsign-compare|i<n", 2}, {"b.cpp|-Wreturn-type|f", 1}};
  Counts current  = {{"a.cpp|-Wshadow|x", 3}, {"a.cpp|-Wsign-compare|i<n", 1},
                     {"b.cpp|-Wreturn-type|f", 1}, {"c.cpp|-Wconversion|len", 2}};
  int total = 0; for (auto& [k, v] : baseline) total += v;
  cout << "baseline warnings: " << total << "\n";
  int added = 0, fixed = 0;
  for (auto& [k, v] : current) {              // new warnings = count above baseline
    int base = baseline.count(k) ? baseline[k] : 0;
    if (v > base) { added += v - base; cout << "NEW   " << k << " (+" << v - base << ")\n"; }
  }
  for (auto& [k, v] : baseline) {             // fixed warnings shrink the baseline
    int cur = current.count(k) ? current[k] : 0;
    if (cur < v) { fixed += v - cur; cout << "FIXED " << k << " (-" << v - cur << ")\n"; }
  }
  cout << "added=" << added << " fixed=" << fixed << " -> CI " << (added ? "FAILS" : "passes") << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Toy target: "crashes" only for input starting with FUZZ. Returns coverage = matched prefix length.
int target(const string& s, bool& crash) {
  const string magic = "FUZZ";
  int depth = 0;
  while (depth < (int)magic.size() && depth < (int)s.size() && s[depth] == magic[depth]) ++depth;
  crash = (depth == 4);
  return depth;
}
int main() {
  mt19937 rng(12345);
  vector<string> corpus = {"AAAA"};            // seed input
  int best = 0;
  for (int iter = 1; iter <= 200000; ++iter) {
    string s = corpus[rng() % corpus.size()];  // pick a seed
    s[rng() % s.size()] = "FUZ!A"[rng() % 5]; // mutate one byte
    bool crash;
    int cov = target(s, crash);
    if (crash) { cout << "crash found after " << iter << " runs with input '" << s << "'\n"; break; }
    if (cov > best) {                          // new coverage: keep as a new seed
      best = cov; corpus.push_back(s);
      cout << "iter " << iter << ": new coverage " << cov << " keep '" << s << "'\n";
    }
  }
  cout << "corpus size " << corpus.size() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
bool decision(bool a, bool b, bool c) { return (a && b) || c; }
int main() {
  const char* names = "abc";
  // Truth table index bits: bit2 = a, bit1 = b, bit0 = c
  auto val = [](int row, int bit) { return (row >> bit) & 1; };
  for (int cond = 0; cond < 3; ++cond) {
    int bit = 2 - cond;
    cout << "condition " << names[cond] << " independence pairs:\n";
    for (int r = 0; r < 8; ++r) {
      int r2 = r ^ (1 << bit);                 // same row with only this condition flipped
      if (r < r2 && decision(val(r,2), val(r,1), val(r,0)) != decision(val(r2,2), val(r2,1), val(r2,0)))
        cout << "  (" << val(r,2) << val(r,1) << val(r,0) << " , " << val(r2,2) << val(r2,1) << val(r2,0) << ")\n";
    }
  }
  // A minimal set that covers a pair for every condition: N+1 = 4 tests
  int pick[] = {0b110, 0b010, 0b100, 0b011};   // TTF, FTF, TFF, FTT
  cout << "minimal test set:";
  for (int r : pick) cout << ' ' << val(r,2) << val(r,1) << val(r,0) << "=>" << decision(val(r,2), val(r,1), val(r,0));
  cout << "\n";
}

#include <bits/stdc++.h>
using namespace std;
using Clock = chrono::steady_clock;
// DoNotOptimize: tell the compiler the value is used, so the work is not deleted
template <class T> void doNotOptimize(T const& v) { asm volatile("" : : "r,m"(v) : "memory"); }

long long sumLoop(const vector<int>& v) { long long s = 0; for (int x : v) s += x; return s; }
long long sumAccumulate(const vector<int>& v) { return accumulate(v.begin(), v.end(), 0LL); }

template <class F> double timeOnce(F f, const vector<int>& v) {
  auto t0 = Clock::now();
  for (int i = 0; i < 200; ++i) { long long r = f(v); doNotOptimize(r); }
  return chrono::duration<double, micro>(Clock::now() - t0).count();
}
template <class F> double medianOf(F f, const vector<int>& v, int reps) {
  vector<double> t;
  for (int i = 0; i < reps; ++i) t.push_back(timeOnce(f, v));   // repetitions, not one run
  sort(t.begin(), t.end());
  return t[t.size() / 2];                                       // median ignores outliers
}
int main() {
  vector<int> data(10000);
  mt19937 rng(1);                                               // seeded: same data every run
  for (int& x : data) x = rng() % 100;                          // setup is outside the timed loop
  cout << "same result? " << (sumLoop(data) == sumAccumulate(data)) << "\n";
  cout << "loop       median (us per 200 calls): " << medianOf(sumLoop, data, 15) << "\n";
  cout << "accumulate median (us per 200 calls): " << medianOf(sumAccumulate, data, 15) << "\n";
  cout << "compare medians over many repetitions, never a single run each\n";
}
